const AB = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function b58(bytes) {
  let nz = 0; while (nz < bytes.length && bytes[nz] === 0) nz++;
  let acc = 0n; for (const b of bytes.slice(nz)) acc = acc * 256n + BigInt(b);
  let out = ''; while (acc > 0n) { out = AB[Number(acc % 58n)] + out; acc /= 58n; }
  return '1'.repeat(nz) + out;
}
function pyrepr(bytes) {
  const has27 = bytes.includes(0x27), has22 = bytes.includes(0x22);
  const q = (has27 && !has22) ? 0x22 : 0x27;
  const qc = String.fromCharCode(q);
  let s = 'b' + qc;
  for (const c of bytes) {
    if (c === 0x5c) s += '\\\\';
    else if (c === q) s += '\\' + qc;
    else if (c === 0x09) s += '\\t';
    else if (c === 0x0a) s += '\\n';
    else if (c === 0x0d) s += '\\r';
    else if (c < 0x20 || c >= 0x7f) s += '\\x' + c.toString(16).padStart(2, '0');
    else s += String.fromCharCode(c);
  }
  return s + qc;
}
